public double myPow(double x, int n) {
    long N = n;
    return helper(x, N);
}

private double helper(double x, long n) {
    if (n == 0) {
        return 1.0;
    }
    if (n < 0) {
        return 1 / helper(x, -n);
    }
    boolean odd = (n & 1) == 1;
    double half = helper(x, n / 2);
    double ans = half * half;
    ans = odd ? ans * x : ans;
    return ans;
}

public double myPow(double x, int n) {
    long N = n;
    return N > 0 ? helper(x, N) : 1 / helper(x, -N);
}

private double helper(double x, long n) {
    if (n == 0) {
        return 1.0;
    }
    double ans = 1;
    while (n != 0) {
        if ((n & 1) == 1) {
            ans *= x;
        }
        x *= x;
        n >>= 1;
    }

    return ans;
}
